1	/**
2	 * adoption-preflight.test.ts — the setup guide, held to the configuration it is a
3	 * guide for.
4	 *
5	 * This is the one document where being wrong costs the most. It is what someone
6	 * reads before their first run, and it had drifted into naming a credential the
7	 * shipped configuration does not use: `OPENAI_API_KEY`, while all three agent
8	 * definitions read `provider: openrouter-responses` -- the router at the time;
9	 * they name `orcarouter-responses` now. Since atoma v0.1.13 one
10	 * provider reads one credential with **no fallback**, so every new adopter
11	 * following the checklist got a failed first run, on the run that is supposed to
12	 * prove the adoption worked.
13	 *
14	 * ## Where the truth lives
15	 *
16	 * The provider table in `docs/agents/reference.md` is the mapping, and this test
17	 * reads it rather than restating it — so there is no third copy to drift. The
18	 * chain is: agent definition names a provider, the table says which credential
19	 * that provider reads, the setup guide must name that credential.
20	 *
21	 * The core is authoritative above all of this: the table itself mirrors
22	 * `PROVIDERS` in atoma's `infra/llm/mod.rs`, and a provider name that atoma does
23	 * not know is what `atoma validate` should reject. This test
24	 * covers the half that lives here.
25	 *
26	 * ## Why it reads a whole file rather than a section
27	 *
28	 * It used to slice the README's "Preflight checklist" and stop at the words "To
29	 * run somewhere else", because the alternatives were named in prose directly below
30	 * the required list and naming them there is the point. `docs/setup.md` is the
31	 * checklist now, and it carries actions only: the alternatives moved to
32	 * `docs/agents/reference.md`, which this test does not police in that direction. So
33	 * the whole page is the required list, and no delimiter has to be kept alive in
34	 * prose for a test to find.
35	 *
36	 * ## The table has to stay on exactly one page
37	 *
38	 * `credentialByProvider()` builds the mapping from one file. A second copy of those
39	 * rows anywhere `docs/setup.md` could grow one would make the negative assertion
40	 * below read a credential as required when it is an alternative, so the rows move
41	 * as a unit or not at all.
42	 *
43	 * ## What the length floor protects, and what it does not
44	 *
45	 * `preflightSection()` keeps a floor of 500 characters, and the floor catches one
46	 * thing: the page emptied or gone, with every assertion after it passing over an
47	 * empty string. It was proposed that the floor be raised to roughly the page's own
48	 * size, so that a checklist thinned into a bare link list would fail. It is not:
49	 * the page is ~2,500 characters of actions and links, a floor set just under that
50	 * fails the next honest edit, and it would report the failure as "docs/setup.md is
51	 * empty or missing", which would be false.
52	 *
53	 * The discipline that actually broke is the opposite one. `docs/setup.md` has no
54	 * artifact of its own, so explanation drifts onto it, and four times it had: two
55	 * paragraphs of `environment.setup_commands`, the `workflow_dispatch` YAML, the
56	 * `gh release download` block and a restatement of the provider rule all stood
57	 * here as second copies of pages in the tree. `the checklist copies nothing from
58	 * the tree` below is the machine-readable half of that: every fenced block on this
59	 * page has to be an action nowhere else under `docs/` performs. It cannot catch a
60	 * paragraph restated in different words -- that is what review is for -- and it
61	 * does not read outside `docs/`, so the copy this page shared with the repository's
62	 * own README was found by hand. Two of the three blocks it does cover had been
63	 * carried for as long as the pages they were copied from had existed.
64	 */
65	import { describe, expect, test } from "bun:test";
66	import { readFileSync, readdirSync, statSync } from "node:fs";
67	import { join } from "node:path";
68	
69	const AGENT_DIR = "src/content/agent-definitions";
70	const SETUP = "docs/setup.md";
71	
72	/** Every Markdown page under a directory, with the separators links are written in. */
73	function markdownUnder(dir: string): string[] {
74	  const found: string[] = [];
75	  for (const entry of readdirSync(dir)) {
76	    const path = `${dir}/${entry}`;
77	    if (statSync(path).isDirectory()) found.push(...markdownUnder(path));
78	    else if (entry.endsWith(".md")) found.push(path);
79	  }
80	  return found;
81	}
82	
83	/** `provider:` from an agent definition's frontmatter. */
84	function providerOf(file: string): string | undefined {
85	  const lines = readFileSync(join(AGENT_DIR, file), "utf8").split(/\r?\n/);
86	  for (const line of lines) {
87	    const match = /^provider:\s*(\S+)\s*$/.exec(line);
88	    if (match?.[1]) return match[1];
89	    if (line === "---" && lines.indexOf(line) > 0) break; // end of frontmatter
90	  }
91	  return undefined;
92	}
